class Solution {
  public int numberOfRoutes(String[] grid, int d) {
    final long MOD = 1_000_000_007L;
    int n = grid.length, m = grid[0].length();
    int reach = (int) Math.floor(Math.sqrt((long) d * d - 1));
    while ((long) (reach + 1) * (reach + 1) + 1 <= (long) d * d) reach++;
    while (reach > 0 && (long) reach * reach + 1 > (long) d * d) reach--;
    long[] prevAll = new long[m];
    long[] free = new long[m], hor = new long[m];
    for (int r = n - 1; r >= 0; r--) {
      free = new long[m];
      hor = new long[m];
      if (r == n - 1) {
        for (int c = 0; c < m; c++) free[c] = grid[r].charAt(c) == '.' ? 1 : 0;
      } else {
        long[] pre = new long[m + 1];
        for (int c = 0; c < m; c++) pre[c + 1] = (pre[c] + prevAll[c]) % MOD;
        for (int c = 0; c < m; c++) {
          if (grid[r].charAt(c) != '.') continue;
          int lo = Math.max(0, c - reach), hi = Math.min(m - 1, c + reach);
          free[c] = ((pre[hi + 1] - pre[lo]) % MOD + MOD) % MOD;
        }
      }
      long[] preFree = new long[m + 1];
      for (int c = 0; c < m; c++) preFree[c + 1] = (preFree[c] + free[c]) % MOD;
      for (int c = 0; c < m; c++) {
        if (grid[r].charAt(c) != '.') continue;
        int lo = Math.max(0, c - d), hi = Math.min(m - 1, c + d);
        hor[c] = ((preFree[hi + 1] - preFree[lo] - free[c]) % MOD + 2 * MOD) % MOD;
      }
      prevAll = new long[m];
      for (int c = 0; c < m; c++) prevAll[c] = (free[c] + hor[c]) % MOD;
    }
    long ans = 0;
    for (int c = 0; c < m; c++) ans += prevAll[c];
    return (int) (ans % MOD);
  }
}
